import sys

MOD = 1_000_000_007


def fib_pair(n):
    # fast doubling: returns (F(n), F(n+1)) mod MOD
    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = (a * ((2 * b - a) % MOD)) % MOD
        d = (a * a + b * b) % MOD
        if bit == '1':
            a, b = d, (c + d) % MOD
        else:
            a, b = c, d
    return a


