import sys

MOD = 1_000_000_007


def fib(n):
    # fast doubling over bits of n, high to low; returns F(n) mod MOD
    a, b = 0, 1
    for i in range(n.bit_length() - 1, -1, -1):
        c = a * ((2 * b - a) % MOD) % MOD
        d = (a * a + b * b) % MOD
        if (n >> i) & 1:
            a = d
            b = (c + d) % MOD
        else:
            a = c
            b = d
    return a


def main():
    out = []
    app = out.append
    for tok in sys.stdin.read().split():
        app(str(fib(int(tok))))
    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
